mapper.select:
select u.user_id , u.user_name , u.email , u.phone , u.user_type , u.status , u.joined_at , u.withdrawn_at , p.product_id , pd.product_name from user u left outer join pay p on u.user_id = p.user_id left outer join product pd on p.product_id = pd.product_id where u.user_type = 'p'
and p.product_id is null
and p.product_id = #{type}
and 1=1
and u.status = #{status}
and u.user_name like concat('%',#{keyword},'%')

select u.user_id , u.user_name , u.email , u.phone , u.user_type , u.status , u.joined_at , u.withdrawn_at , p.birth_date , p.gender , p.country , p.pass_count , p.report_received_count , p.profile_url from user u join user_person p on u.user_id = p.user_id where u.user_type = 'p' and u.status = 'WITHDRAWN'
and u.user_name like concat('%',#{keyword},'%')
and date(u.withdrawn_at) between #{startDate} and #{endDate}

select u.user_id , u.user_name , u.email , u.phone , u.user_type , u.status , u.joined_at , u.withdrawn_at , c.biz_reg_no , c.company_name , c.ceo_name , c.company_address , p.product_id , pd.product_name from user u join user_company c on u.user_id = c.user_id left outer join pay p on u.user_id = p.user_id left outer join product pd on p.product_id = pd.product_id where u.user_type = 'c'
and p.product_id is null
and p.product_id = #{type}
and 1=1
and u.status = #{status}
and c.company_name like concat('%',#{keyword},'%')

select u.user_id , u.user_name , u.email , u.phone , u.user_type , u.status , u.joined_at , u.withdrawn_at , c.biz_reg_no , c.company_name , c.ceo_name , c.company_address from user u join user_company c on u.user_id = c.user_id where u.user_type = 'c' and u.status = 'WITHDRAWN'
and c.company_name like concat('%',#{keyword},'%')
and date(u.withdrawn_at) between #{startDate} and #{endDate}

mapper.insert:
INSERT INTO notice (
	notice_title
	, notice_content
	, reg_date
	, readcount
	, user_type
	, status
) VALUES (
	#{notice_title}
	, #{notice_content}
	, NOW()
	,0
	, #{user_type}
	, #{status}
)

mapper.update:
UPDATE notice
SET readcount = readcount + 1
WHERE notice_id = #{notice_id}

mapper.select:
select j.job_id ,j.comp_id ,c.company_name ,j.title ,j.field ,j.task ,j.emp_type ,j.probation ,j.exp_type ,j.exp_year ,j.edu ,j.salary ,j.address ,j.is_remote ,j.mgr_name ,j.mgr_phone ,j.mgr_email ,j.is_public ,j.open_date ,j.close_date ,j.post_status ,j.reg_date ,j.post_check from job_posting j join user_company c on j.comp_id = c.user_id where 1=1
and date(j.reg_date) between #{startDate} and #{endDate}
and c.company_name like concat('%',#{keyword},'%')
and j.post_check = #{submitStatus}

select p.pay_id , p.user_id , u.user_name , u.phone , u.user_type , p.product_id , pd.product_name , p.pay_method , p.card_name , p.bank_name , p.deposit_account , p.deposit_name , p.pay_price , p.pay_date , p.pay_status from pay p join product pd on p.product_id = pd.product_id join user u on p.user_id = u.user_id where 1=1
and date(p.pay_date) between #{startDate} and #{endDate}
and pd.product_name like concat('%',#{keyword},'%')
and u.user_type = #{userType}
and p.pay_status = #{payStatus}
